import{_ as i,a0 as a,w as s,s as l,ao as u,I as p,x as e,a1 as o,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"安装完最小化 RHEL/CentOS 7 后需要做的 30 件事情（六） | LCTT x X-CMD","titleTemplate":false,"description":"安装完最小化 RHEL/CentOS 7 后需要做的 30 件事情（六） | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安装完最小化 RHEL/CentOS 7 后需要做的 30 件事情（六） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安装完最小化 RHEL/CentOS 7 后需要做的 30 件事情（六） | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/30 Things to Do After Minimal RHEL or CentOS 7 Installation--6","title":"安装完最小化 RHEL/CentOS 7 后需要做的 30 件事情（六）","tag":"201505","desc":""},"relativePath":"201505/30 Things to Do After Minimal RHEL or CentOS 7 Installation--6.md","filePath":"[post].md"}'),m={name:"201505/30 Things to Do After Minimal RHEL or CentOS 7 Installation--6.md"};function d(g,t,b,c,w,f){const n=a("Link");return s(),l("div",null,[t[13]||(t[13]=u(`<h1 id="安装完最小化-rhel-centos-7-后需要做的-30-件事情-六" tabindex="-1">安装完最小化 RHEL/CentOS 7 后需要做的 30 件事情（六） <a class="header-anchor" href="#安装完最小化-rhel-centos-7-后需要做的-30-件事情-六" aria-label="Permalink to “安装完最小化 RHEL/CentOS 7 后需要做的 30 件事情（六）”">​</a></h1><h3 id="_30-用密码保护-grub" tabindex="-1">30. 用密码保护 GRUB <a class="header-anchor" href="#_30-用密码保护-grub" aria-label="Permalink to “30. 用密码保护 GRUB”">​</a></h3><p>用密码保护你的 boot 引导程序这样你就可以在启动时获得额外的安全保障。同时你也可以在实物层面获得保护。通过在引导时给 GRUB 加锁防止任何无授权访问来保护你的服务器。</p><p>首先备份两个文件，这样如果有任何错误出现，你可以有回滚的选择。备份 ‘/etc/grub2/grub.cfg’ 为 ‘/etc/grub2/grub.cfg.old’。</p><pre><code># cp /boot/grub2/grub.cfg /boot/grub2/grub.cfg.old
</code></pre><p>同样，备份 ‘/etc/grub.d/10_linux’ 为 ‘/etc/grub.d/10_linux.old’。</p><pre><code># cp /etc/grub.d/10_linux /etc/grub.d/10_linux.old
</code></pre><p>打开文件 ‘/etc/grub.d/10_linux’ 并在文件末尾添加下列行。</p><pre><code>cat &lt;&lt;EOF
set superusers=&quot;tecmint&quot;
Password tecmint avi@123
EOF
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Password-Protect-Grub.png" alt="密码保护 Grub"></p><p><em>密码保护 Grub</em></p><p>注意在上面的文件中，用你自己的用户名和密码代替 “tecmint” 和 “avi@123”。</p><p>现在通过运行下面的命令生成新的 grub.cfg 文件。</p><pre><code># grub2-mkconfig --output=/boot/grub2/grub.cfg
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Generate-Grub-File.jpeg" alt="生成 Grub 文件"></p><p><em>生成 Grub 文件</em></p><p>创建 grub.cfg 文件之后，重启机器并敲击 ‘e’ 进入编辑。你会发现它会要求你输入 “有效验证” 来编辑 boot 菜单。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Edit-Boot-Menu.jpeg" alt="有密码保护的 Boot 菜单"></p><p><em>有密码保护的 Boot 菜单</em></p><p>输入登录验证之后，你就可以编辑 grub boot 菜单。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Grub-Menu-Edit.jpeg" alt="Grub 菜单文件"></p><p><em>Grub 菜单文件</em></p><p>你也可以用加密的密码代替上一步的明文密码。首先按照下面推荐的生成加密密码。</p><pre><code># grub2-mkpasswd-pbkdf2

[两次输入密码]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Generate-Encrypted-Grub-Password.jpeg" alt="生成加密的 Grub 密码"></p><p><em>生成加密的 Grub 密码</em></p><p>打开 ‘/etc/grub.d/10_linux’ 文件并在文件末尾添加下列行。</p><pre><code>cat &lt;&lt;EOF
set superusers=”tecmint”
Password_pbkdf2 tecmint
grub.pbkdf2.sha512....你的加密密码....
EOF
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Encrypted-Grub-Password.jpeg" alt="加密 Grub 密码"></p><p><em>加密 Grub 密码</em></p><p>用你系统上生成的密码代替原来的密码，别忘了交叉检查密码。</p><p>同样注意在这种情况下你也需要像上面那样生成 grub.cfg。重启并敲击 ‘e’ 进入编辑，会提示你输入用户名和密码。</p><p>我们已经介绍了大部分工业标准发行版 RHEL 7 和 CentOS 7 安装后必要的操作。如果你发现我们缺少了一些点或者你有新的东西可以扩充这篇文章，你可以和我们一起分享，我们会通过扩充在这篇文章中包括你的分享。</p><hr>`,34)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://www.tecmint.com/things-to-do-after-minimal-rhel-centos-7-installation/6/"},{default:r(()=>[...t[0]||(t[0]=[e("http://www.tecmint.com/things-to-do-after-minimal-rhel-centos-7-installation/6/",-1)])]),_:1})]),p("p",null,[t[5]||(t[5]=e("作者：",-1)),o(n,{href:"http://www.tecmint.com/author/avishek/"},{default:r(()=>[...t[2]||(t[2]=[e("Avishek Kumar",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),o(n,{href:"https://github.com/ictlyh"},{default:r(()=>[...t[3]||(t[3]=[e("ictlyh",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[10]||(t[10]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创翻译，",-1)),o(n,{href:"http://linux.cn/"},{default:r(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const _=i(m,[["render",d]]);export{T as __pageData,_ as default};
